; The runtime's declarations (the build expands the list: src/runtime/head.txt)
; mput ../../runtime/head.txt
; AUTOINC:BEGIN (do not edit -- managed by scripts/gen-includes.js)
            REL
            use   Locator.Macs
            use   Load.Macs
            use   Mem.Macs
            use   Misc.Macs
            use   Util.Macs
            use   EDS.GSOS.Macs
            use   GTE.Macs.s
            put    ../../Externals.s
            put    ../../core/Defs.s
            put    ../../rom/rom_kbd_macs.s
            put    ../../ImportEngine.s
; AUTOINC:END

; The game's configuration (constants) and its callbacks (Hooks.s, macros only: put after the entry code)
            put   Config.s
            put   pal_defs.s                  ; Palette ids (generated from palettes/)

            mx    %00

            phk
            plb

; Call startup immediately after entering the application with the cartridge configuration

            tax                           ; X = memory manager user ID (passed in A by GS/OS)
            lda   #VERTICAL_MIRRORING      ; A = cartridge nametable mirroring at power on
            jsr   NES_StartUp

; Initialize the graphics for the main game mode

            jsr   SetDefaultPalette

; Put the figures into the OAM buffer

            jsr   BenchInit

; Call the boot code in the ROM

            jsr   NES_ColdBoot

; Start up the NES
:start
            jsr   NES_EvtLoop

            cmp   #USER_SAYS_QUIT
            beq   quit

            cmp   #USER_SAYS_RESET
            bne   quit

            jsr   NES_WarmBoot
            bra   :start

; The user has existed the runtime
quit
            jsr   NES_ShutDown

; Exit the application

            _QuitGS    qtRec
qtRec       adrl  $0000
            da    $00

; Name of the save and preference files
SAVE_FILENAME strl '1/bench.sav'
PREF_FILENAME strl '1/bench.prefs'

; The figures: sprites.s (generated by make-scene.js) has their OAM entries and, for each step of the
; walk animation, the tile and attribute bytes of every entry
            put   sprites.s

; The engine callbacks (the macros; the code they call is below, and the engine side's in EngineExt.s)
            put   Hooks.s

; ===========================================================================
; The game's code: start-up, the event loop and frame hooks
; ===========================================================================
            mx    %00

            ERR   BENCH_SPRITES-OAM_END_INDEX   ; OAM_END_INDEX must be the number of sprites
benchTop ENT
                dw  0                     ; first screen line of the playfield (200 - its height)
benchLines ENT
                dw  200                   ; height of the playfield

; The playfield sizes of the keys 1 - 3: the first screen line and the number of lines.  The first line
; must be even (FAST BLIT draws every other line).
BenchSizeTop    dw  0,24,40
BenchSizeLines  dw  200,176,160

; Copy the figures' OAM entries into the NES OAM buffer (DIRECT_OAM_READ).  The positions never change.
; Also (re)starts the scrolling and the animation.
            mx    %00
BenchInit
            lda   #0

            stal   benchScrollX
            lda   #0

            stal   benchScroll
            lda   #0

            stal   benchAnimOfs
            lda   #BENCH_ANIM_RENDERS
            stal   benchAnimTimer
            ldx   #0
:loop       lda   BenchOAMInit,x
            stal  ROMBase+DIRECT_OAM_READ,x
            inx
            inx
            cpx   #BENCH_SPRITES*4
            bcc   :loop
            rts

; EVT_LOOP_END, on the GS task (between renders): the keys 1 - 3 pick the playfield size.  Clear the
; screen, give the lines above the playfield the black palette and restart the demo.  A = the key code.
            mx    %00
BenchKey
            and   #$007F
            sec
            sbc   #'1'
            cmp   #3
            bcs   :out
            asl
            tax
            lda   BenchSizeTop,x
            sta   benchTop
            lda   BenchSizeLines,x
            sta   benchLines
            jsr   _ClearShadowScreen        ; both the shadow screen and the SHR screen
            jsl   BenchSetSCBs
            jsr   BenchInit
            rtl
:out        rtl

; The SCBs: the lines above the playfield use palette 1, black with a white color 15 (the FPS digits),
; and the playfield uses palette 0
            mx    %00
BenchSetSCBs
            ldx   #30
            lda   #$0FFF
:pal        stal  SHR_PALETTES+32,x
            lda   #$0000
            dex
            dex
            bpl   :pal

            ldx   #0
            sep   #$20
:scb        lda   #$01
            cpx   benchTop
            bcc   *+4
            lda   #$00
            stal  SHR_SCB,x
            inx
            cpx   #200
            bcc   :scb
            rep   #$20
            rtl

; Start-up (NES_StartUp).  The palettes are managed by the code generated from palettes/
; (pal_transitions.s): SetDefaultPalette, and ApplyPaletteChange, the PRE_RENDER hook.
InitPlayfield
            jmp   SetDefaultPalette

            mx    %00

; The palette management generated from palettes/ (ApplyPaletteChange)
            put   pal_transitions.s

; The render screen (CUSTOM_RENDER_SCREEN_ADDR, see ppu/ppu_api.s): a full render of the playfield lines
; only.  The lines above it are never drawn, so they stay as BenchKey cleared them.
            mx    %00
BenchRenderScreen ENT
            ldal  _ppuscroll_y
            tay
            ldal  _ppuscroll_x
            tax
            ldal  _ppuctrl
            jsl   NES_SetScroll
            ldal  benchLines
            tax
            ldal  benchTop
            jsl   PPU_DrawScreenRange
            lda   #0                      ; Drawn: DirtyBits = 0
            sec
            rtl

            mx    %00

benchScrollX    dw  0                     ; horizontal scroll position, 0 - 511
benchScroll     dw  0                     ; the scroll for the render: X in the high byte, Y (0) in the low byte
benchAnimTimer  dw  BENCH_ANIM_RENDERS    ; renders left until the next animation step
benchAnimOfs    dw  0                     ; offset of the current step in BenchOAMAnim

; The control lock (CUSTOM_PPU_CTRL_LOCK_ADDR, see ppu/ppu_api.s): called for each render, before the
; scroll is latched and the OAM is scanned (interrupts off).  Scroll one step to the left and, every
; BENCH_ANIM_RENDERS renders, write the tile and attribute bytes of the next animation step into the
; OAM buffer.  Returns A = the PPUCTRL value for the render, with the nametable of the scroll position.
            mx    %00
BenchStep ENT
            phb
            phk
            plb
            dec   benchAnimTimer
            bne   :scroll
            jsr   BenchAnimate

:scroll     lda   benchScrollX
            clc
            adc   #BENCH_SCROLL_STEP
            and   #$01FF
            sta   benchScrollX
            xba                           ; X & $FF in the high byte, the nametable bit in the low byte
            tax
            and   #$FF00
            sta   benchScroll
            txa
            and   #$0001
            ora   #BENCH_PPUCTRL
            plb
            sec
            rtl

; The scroll lock (CUSTOM_PPU_SCROLL_LOCK_ADDR): the scroll BenchStep set
            mx    %00
BenchScrollLock ENT
            ldal  benchScroll
            sec
            rtl

; The next step of the walk animation: only the tile and attribute bytes of the OAM entries change
            mx    %00
BenchAnimate
            lda   #BENCH_ANIM_RENDERS
            sta   benchAnimTimer

            lda   benchAnimOfs
            clc
            adc   #BENCH_SPRITES*2
            cmp   #BENCH_SPRITES*2*BENCH_ANIM_STEPS
            bcc   *+5
            lda   #0
            sta   benchAnimOfs
            tax
]n          =     0
            lup   OAM_END_INDEX
            lda   BenchOAMAnim+{]n*2},x
            stal  ROMBase+DIRECT_OAM_READ+1+{]n*4}    ; tile and attributes
]n          =     ]n+1
            --^
            rts

            mx    %00

; The runtime's code (the build expands the list: src/runtime/code.txt)
            mput  ../../runtime/code.txt
; AUTOINC:BEGIN (do not edit -- managed by scripts/gen-includes.js)
            put    ../../misc/App.Msg.s
            put    ../../misc/io.s
            put    ../../apu/apu.s
            put    ../../rom/scaffold.s
            put    ../../rom/rom_color.s
            put    ../../rom/rom_helpers.s
            put    ../../rom/rom_input.s
            put    ../../rom/rom_kbd_basic.s
            put    ../../rom/rom_exec.s
            put    ../../rom/rom_config.s
            put    ../../rom/rom_config_setup.s
            put    ../../core/ControlBits.s
            put    ../../core/CoreImpl.s
            put    ../../core/Graphics.s
            put    ../../core/Math.s
            put    ../../core/Memory.s
; AUTOINC:END
